import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"風火家人","description":"周易折中 - 風火家人","frontmatter":{"title":"風火家人","description":"周易折中 - 風火家人"},"headers":[],"relativePath":"classics/zhezhong/043.md","filePath":"classics/zhezhong/043.md"}'),h={name:"classics/zhezhong/043.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="風火家人" tabindex="-1">風火家人 <a class="header-anchor" href="#風火家人" aria-label="Permalink to “風火家人”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>〈家人〉序卦：“夷者，傷也。傷於外者，必反於家，故受之以《家人》。夫傷困於外，則必反於內，《家人》所以次《明夷》也。《家人》，家內之道也。父子之親，夫婦之義，尊卑長幼之序，正倫理，篤恩義，家人之道也。卦外巽內離，為風自火出，火熾則風生，風生自火，自內而出也。自內而出，由家而及於外之象。二與五正男女之位，於內外為《家人》之道。明於內而巽於外，處家之道也。夫人有諸身者，則能施於家；行於家者，則能施於國；至於天下治，治天下之道，蓋治家之道也。推而行之於外耳，故取自內而出之象，為《家人》之義也。文中子書以明內齊外為義，古今善之，非取象之意也。所謂齊乎巽，言萬物潔齊於巽方，非巽有齊義也，如戰乎乾，乾非有戰義也。”</p><p>家人：利女貞</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>家人者，一家之人。卦之九五、六二外內各得其正，故為家人。利女貞者，欲先正乎內也，內正則外無不正矣。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>家人之道，利在女正。女正則家道正矣。夫夫婦婦而家道正，獨雲“利女貞”者，夫正者身正也，女正者家正也。女正則男正可知矣。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏時曰 ：家人者，治家人之道也。齊家自夫婦始。舜觀刑于二女，文王刑于寡妻，至於兄弟。利女貞者，言家道之本也。</li></ul><p>楊氏時曰 ：家人者，治家人之道也。齊家自夫婦始。舜觀刑于二女，文王刑于寡妻，至於兄弟。利女貞者，言家道之本也。</p><ul><li>林氏希元曰 ：所正雖在女，所以正之者則在夫，蓋主家之人也。</li></ul><p>林氏希元曰 ：所正雖在女，所以正之者則在夫，蓋主家之人也。</p><p>象曰：風自火出，家人；君子以言有物而行有恆</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>身脩則家治矣</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>正家之本在正其身。正身之道，一言一動不可易也。君子觀風自火出之象，知事之由內而出，故所言必有物，所行必有恆也。物謂事實，恆謂常度法則也。德業之著於外，由言行之謹於內也。言愼行脩，則身正而家治矣。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎達曰：物，事也。言必有事，即口無擇言；行必有常，即身無擇行。正家之義，脩於近小。言之與行，君子樞機。出身加人，發邇化遠，故舉言行以為之誡。</p></li><li><p>楊氏時曰：言忠信則有物，行篤敬則有常。</p></li><li><p>胡氏炳文曰：風自火出，一家之化自吾言行出，皆由內及外，自然薰蒸而成者也。</p></li><li><p>俞氏琰曰：齊家之道，自脩身始。此風自火出，所以為家人之象也。君子知風之自是，齊家以脩身為本，而脩身以言行為先。言必有物而無妄，行必有恆而不改。物謂事實，言而誠實則有物，不誠實則無物也；恆謂常度，行而常久則有恆，不常久則無恆也。</p></li></ul><p>彖曰：家人，女正位乎內，男正位乎外，男女正，天地之大義也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>以卦體九五六二釋“利女貞”之義。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>彖以卦才而言，陽居五在外也，陰居二處內也。男女各得其正位也，尊卑內外之道正合天地陰陽之大義也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>孔氏穎逹曰 ：此因二五得正以釋家人之義，並明“女貞”之㫖。</p></li><li><p>吳氏曰慎曰 ：先言“女正位乎內”，釋“利女貞”也。</p></li></ul><p>家人有嚴君焉，父母之謂也</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>亦謂二五。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>家人之道必有所尊嚴而君長者，謂父母也。雖一家之小，無尊嚴則孝敬衰，無君長則法度廢。有嚴君而後家道正，家者國之則也。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏申子曰 ：父道固主乎嚴，母道尤不可以不嚴。猶國有尊嚴之君長也，無尊嚴則孝敬衰，無君長則法度廢。故家人一卦大要以剛嚴為尚。</li></ul><p>父父子子，兄兄弟弟，夫夫婦婦，而家道正；正家而天下定矣</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>上父初子，五三夫，四二婦，五兄三弟（以卦畫推之，又有此象）。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>父子、兄弟、夫婦各得其道，則家道正矣。推一家之道可以及天下，故家正則天下定矣。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>俞氏琰曰 ：彖辭舉其端，故但言“利女貞”。彖傳極其全，故兼言男女之正，而又以父子、兄弟、夫婦推廣而備言之。</p></li><li><p>林氏希元曰 ：“正家而天下定”猶雲“人人親其親，長其長而天下平”，不作“正家”之效說。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>六十四卦六爻剛柔皆得位者，惟既濟而已。此外則中四爻得位者三卦，家人、蹇、漸也。然家人名義獨取於風火之卦者，一則風自火出，為風化有原之象；二則蹇、漸之中爻雖得位而初上不皆陽爻。凡易取類，上爻有父之象，故蠱卦下五爻皆曰“父母”，至上爻則變其文也。初爻有子之象，故蠱曰“有子”，觀曰“童觀”，隨、漸曰“小子”，中孚曰“其子”，皆指初爻也。二為女正位乎內，母道也；五為男正位乎外，父道也。然必初上皆陽，然後父子之象備；又必三陽四陰各得其位，然後兄弟、夫婦粲然於一卦之中矣。彖傳先舉二五，始明其為男女之正，繼明其為父母之嚴，以兩爻為卦主也。然後悉推家人以切卦位，既以盡正家之義，又以見家人之象。推配於爻畫者，獨此卦為合也。本義精且當矣。</p><p>初九：閒有家，悔亡</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>初九以剛陽處有家之始，能防閒之，其悔亡矣。戒佔者當如是也。</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>初，家道之始也。閒，謂防閒法度也。治其有家之始，能以法度為之防閒，則不至於悔矣。治家者，治乎眾人也。苟不閒之以法度，則人情流放，必至於有悔，失長幼之序，亂男女之別，傷恩義，害倫理，無所不至。能以法度閒之於始，則無是矣。故悔亡也。九，剛明之才，能閒其家者也。不雲“無悔”者，群居必有悔，以能閒故亡耳。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：凡教在初而法在始，家瀆而後嚴之，志變而後治之，則悔矣。處家人之初，為家人之始，故必閒有家，然後悔亡也。</li></ul><p>王氏弼曰 ：凡教在初而法在始，家瀆而後嚴之，志變而後治之，則悔矣。處家人之初，為家人之始，故必閒有家，然後悔亡也。</p><ul><li>胡氏炳文曰 ：初之時當閒，九之剛能閒。</li></ul><p>胡氏炳文曰 ：初之時當閒，九之剛能閒。</p><ul><li>顏之推曰 ：教子嬰孩，教婦初來。</li></ul><p>顏之推曰 ：教子嬰孩，教婦初來。</p><p>象曰：閒有家，志未變也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>志未變而豫防之</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>閒之於始，家人志意未變動之前也。正志未流散變動而閒之，則不傷恩，不失義，處家之善也。是以悔亡。志變而後治，則所傷多矣，乃有悔也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰：忘閒焉，則志變矣。及其未變而閒之，故悔亡。</p></li><li><p>楊氏簡曰：治家之道，當防閒其初。及其心志未變而閒之以禮，邪僻之意無由而興矣。</p></li></ul><p>六二：無攸遂，在中饋，貞吉</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>六二柔順中正，女之正位乎內者也，故其象佔如此。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>人之處家在骨肉父子之閒，大率以情勝禮，以恩奪義。惟剛立之人，則能不以私愛失其正理。故家人卦大要以剛為善，初、三、上是也。六二以陰柔之才而居柔，不能治於家者也，故無攸遂，無所為而可也。夫以英雄之才，尚有溺情愛而不能自守者，況柔弱之人，其能勝妻子之情乎？如二之才，若為婦人之道，則其正也。以柔順處中正，婦人之道也。故在中饋，則得其正而吉也。婦人居中而主饋者也，故云“中饋”。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li>孔氏穎逹曰 ：六二履中居位，以陰應陽，盡婦人之義也。婦人之道，巽順為常，無所必遂。其所職主在於家，中饋食供祭而已。得婦人之正，故曰“無攸遂，在中饋，貞吉”。</li></ul><p>孔氏穎逹曰 ：六二履中居位，以陰應陽，盡婦人之義也。婦人之道，巽順為常，無所必遂。其所職主在於家，中饋食供祭而已。得婦人之正，故曰“無攸遂，在中饋，貞吉”。</p><ul><li>王氏宗傳曰 ：“無攸遂”示不敢有所專也。婦人之職，不過奉祭祀、饋飲食而已，此外無他事也。《詩》曰：“無非無儀，惟酒食是議。”采蘩以供祭祀為不失職，採蘋以供祭祀為能循法度。推而上之，推而下之，其職守莫不皆然，是之謂貞而吉也。</li></ul><p>王氏宗傳曰 ：“無攸遂”示不敢有所專也。婦人之職，不過奉祭祀、饋飲食而已，此外無他事也。《詩》曰：“無非無儀，惟酒食是議。”采蘩以供祭祀為不失職，採蘋以供祭祀為能循法度。推而上之，推而下之，其職守莫不皆然，是之謂貞而吉也。</p><ul><li>易氏祓曰 ：六二柔順得位，與九五相應，女正位乎內者也。此爻正所以發明“利女貞”之義。</li></ul><p>易氏祓曰 ：六二柔順得位，與九五相應，女正位乎內者也。此爻正所以發明“利女貞”之義。</p><p>象曰：六二之吉，順以巽也</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>二以陰柔居中正，能順從而卑巽者也，故為婦人之貞吉也。</p><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>六二六四之為順同。順者，女之貞也。四位高，故曰順；在位二，位卑，故曰順以巽。</p><p>九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>以剛居剛而不中，過乎剛者也，故有嗃嗃嚴厲之象。如是則雖有悔厲而吉也。嘻嘻者，嗃嗃之反，吝之道也。佔者各以其德為應，故兩言之。</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>嗃嗃，未詳字義，然以文義及音意觀之，與嗷嗷相類，又若急束之意。九三在內卦之上，主治乎內者也。以陽居剛而不中，雖得正而過乎剛者也。治內過剛，則傷於嚴急，故家人嗃嗃然。治家過嚴，不能無傷，故必悔於嚴厲。骨肉恩勝嚴過，故悔也。雖悔於嚴厲，未得寛猛之中，然而家道齊肅，人心祗畏，猶為家之吉也。若婦子嘻嘻，則終至羞吝矣。在卦非有嘻嘻之象，蓋對嗃嗃而言，謂與其失於放肆，寧過於嚴也。嘻嘻，笑樂無節也。自恣無節，則終至敗家，可羞吝也。蓋嚴謹之過，雖於人情不能無傷，然苟法度立，倫理正，乃恩義之所存也。若嘻嘻無度，乃法度之所由廢，倫理之所由亂，安能保其家乎？嘻嘻之甚，則致敗家之兇，但云“吝”者，吝之甚則至於兇，故未遽言兇也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>朱子語類 問：易傳雲正家之道，在於正倫理、篤恩義。今欲正倫理，則有傷恩義；欲篤恩義，又有乖於倫理，如何？ 曰：須是於正倫理處篤恩義，篤恩義而不失倫理，方可。</li></ul><p>朱子語類</p><ul><li><p>問：易傳雲正家之道，在於正倫理、篤恩義。今欲正倫理，則有傷恩義；欲篤恩義，又有乖於倫理，如何？ 曰：須是於正倫理處篤恩義，篤恩義而不失倫理，方可。</p></li><li><p>胡氏炳文曰 ：嗃嗃以義勝情，雖悔厲而吉；嘻嘻以情勝義，終吝。悔自兇而吉，吝自吉而兇。九三以剛居剛，若能嚴於家人者，比乎二柔；又若易暱於婦子者，三其在吉凶之閒乎？故悔吝之佔兩言之。</p></li></ul><p>胡氏炳文曰 ：嗃嗃以義勝情，雖悔厲而吉；嘻嘻以情勝義，終吝。悔自兇而吉，吝自吉而兇。九三以剛居剛，若能嚴於家人者，比乎二柔；又若易暱於婦子者，三其在吉凶之閒乎？故悔吝之佔兩言之。</p><p>象曰：家人嗃嗃，未失也；婦子嘻嘻，失家節也</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>雖嗃嗃於治家之道，未為甚失。若婦子嘻嘻，是無禮法，失家之節，家必亂矣。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰：以陽處陽，剛嚴者也。處下體之極，為一家之長者也。行與其慢，寧過乎恭；家與其瀆，寧過乎嚴。是以家人雖嗃嗃悔厲，猶得其道；婦子嘻嘻，乃失其節也。</li></ul><p>六四：富家，大吉</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>陽主義，陰主利。以陰居陰而在上位，能富其家者也。</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>六以巽順之體而居四，得其正位。位居得其正，為安處之義。巽順於事而由正道，能保有其富者也。居家之道，能保有其富，則為大吉也。四髙位而獨雲“富”者，於家而言，髙位家之尊也。能有其富，是能保其家也，吉孰大焉。</p><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>四在他卦，臣道也；在《家人》卦，則亦妻道也。夫主教一家者也，婦主養一家者也。老子所謂“教父食母”是也。自二之“在中饋”進而至於四之“富家”，則內職舉矣。</p><p>象曰：富家大吉，順在位也</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>以巽順而居正位，正而巽順，能保有其富者也。富家之大吉也。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>俞氏琰曰：《禮運》雲：“父子篤，兄弟睦，夫婦和，家之肥也。”豈以多財為吉哉？以順居之，則滿而不溢，可以保其家而長守其富，吉孰大焉？</li></ul><p>九五：王假有家，勿恤吉</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>假，至也。如“假於大廟”之假。有家，猶言有國也。九五剛健中正，下應六二之柔順中正，王者以是至於其家，則勿用憂恤而吉可必矣。蓋聘納后妃之吉占，而凡有是德者遇之皆吉也。</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>九五男而在外，剛而處陽，居尊而中正，又其應順正於內，治家之至正至善者也。王假有家，五君位，故以王言。假至也，極乎有家之道也。夫王者之道，修身以齊家，家正而天下治矣。自古聖王未有不以恭巳正家為本，故有家之道既至，則不憂勞而天下治矣。勿恤而吉也。五恭巳於外，二正家於內，內外同德，可謂至矣。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li>楊氏文煥曰 ：閒有家，閒之於其始；假有家，則假之於其終也。</li></ul><p>楊氏文煥曰 ：閒有家，閒之於其始；假有家，則假之於其終也。</p><ul><li>丘氏富國曰 ：三五陽剛皆主治家者也。三則而不中，失之遇嚴，未免有悔厲之失；五剛而得中，威而能愛，盡乎治家之道者，故人無不化，可以勿憂恤而吉也。或曰：治家之道尚嚴，在彖以嚴正為吉，五以相愛為義，何也？曰：嚴以分言正家之義也，愛以情言假家之弟也。假有感格之義，故以相愛言之。</li></ul><p>丘氏富國曰 ：三五陽剛皆主治家者也。三則而不中，失之遇嚴，未免有悔厲之失；五剛而得中，威而能愛，盡乎治家之道者，故人無不化，可以勿憂恤而吉也。或曰：治家之道尚嚴，在彖以嚴正為吉，五以相愛為義，何也？曰：嚴以分言正家之義也，愛以情言假家之弟也。假有感格之義，故以相愛言之。</p><ul><li>龔氏煥曰 ：假與格同，猶“奏假無言，昭假烈祖”之假，謂感格也。九五以陽剛中正居尊位，為有家之主，盛德至善，所以感格乎家人之心者至矣。王者家大人眾，其心難一，有未假者，勿用憂恤而自吉也。蓋初之“閒有家”是以法度防閒之，至“王假有家”則躬行有以感化之矣。</li></ul><p>龔氏煥曰 ：假與格同，猶“奏假無言，昭假烈祖”之假，謂感格也。九五以陽剛中正居尊位，為有家之主，盛德至善，所以感格乎家人之心者至矣。王者家大人眾，其心難一，有未假者，勿用憂恤而自吉也。蓋初之“閒有家”是以法度防閒之，至“王假有家”則躬行有以感化之矣。</p><ul><li>何氏楷曰 ：舜格於文祖，公假於太廟，格、假互用可證。身範既端，故能感格其家，使父父子子、兄兄弟弟、夫夫婦婦各得其所以相敦睦，正家而天下定，故不待憂恤而吉也。</li></ul><p>何氏楷曰 ：舜格於文祖，公假於太廟，格、假互用可證。身範既端，故能感格其家，使父父子子、兄兄弟弟、夫夫婦婦各得其所以相敦睦，正家而天下定，故不待憂恤而吉也。</p><ul><li>遊氏曰 ：九五尊位，故以王言。假者，感格之義，王假有廟，其義同也。</li></ul><p>遊氏曰 ：九五尊位，故以王言。假者，感格之義，王假有廟，其義同也。</p><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>假字訓感格，諸說皆有明證可從。何氏之說於象傳之義尤為浹洽也。</p><p>象曰：王假有家，交相愛也</p><h3 id="本義-11" tabindex="-1">本義 <a class="header-anchor" href="#本義-11" aria-label="Permalink to “本義”">​</a></h3><p>程子曰：夫愛其內助，婦愛其刑家</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>王假有家之道者，非止能使之順從而已，必致其心化誠合。夫愛其內助，婦愛其刑家，交相愛也。能如是者，文王之妃乎？若身脩法立而家未化，未得為假有家之道也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>郭氏雍曰：父父子子，兄兄弟弟，夫夫婦婦，同大順而無逆焉者，交相愛之義也。</p></li><li><p>龔氏煥曰：交相愛，則一家之父子、兄弟、夫婦、長幼莫不相愛，非特夫婦而已也。</p></li></ul><p>上九：有孚威如，終吉</p><h3 id="本義-12" tabindex="-1">本義 <a class="header-anchor" href="#本義-12" aria-label="Permalink to “本義”">​</a></h3><p>上九以剛居上，在卦之終，故言正家乆遠之道。佔者必有誠信嚴威，則終吉也。</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>上卦之終，家道之成也。故極言治家之本。治家之道，非至誠不能也，故必中有孚信。則能常乆而眾人自化為善，不由至誠已且不能常守也，況欲使人乎？故治家以有孚為本。治家者在妻孥情愛之閒，慈過則無嚴，恩勝則掩義，故家之患常在禮法不足而瀆慢生也。長失尊嚴，少忘恭順，而家不亂者未之有也。故必有威嚴，則能終吉。保家之終，在有孚威如二者而已，故於卦終言之。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li>王氏弼曰 ：家道可終，惟信與威。</li></ul><p>王氏弼曰 ：家道可終，惟信與威。</p><ul><li>蘇氏軾曰 ：凡言終者，其始未必然也。婦子嘻嘻，其始可樂；威如之吉，其始苦之。</li></ul><p>蘇氏軾曰 ：凡言終者，其始未必然也。婦子嘻嘻，其始可樂；威如之吉，其始苦之。</p><ul><li>王氏申子曰 ：家人之終，家道成也。故極言齊家乆逺之道。齊家之道，以誠為本，以嚴為用。不誠則上下相欺，眾事不立；不嚴則禮法不存，瀆慢易生。如此而家道齊者，未之有也。故家人之終，以孚威二者言之。是二者保家道之終吉者也。</li></ul><p>王氏申子曰 ：家人之終，家道成也。故極言齊家乆逺之道。齊家之道，以誠為本，以嚴為用。不誠則上下相欺，眾事不立；不嚴則禮法不存，瀆慢易生。如此而家道齊者，未之有也。故家人之終，以孚威二者言之。是二者保家道之終吉者也。</p><ul><li>何氏楷曰 ：治家觀於身，下五爻未及正身之義，故於此爻足其意。蓋探本之論，與大象言“有物行有恆”相表裡。</li></ul><p>何氏楷曰 ：治家觀於身，下五爻未及正身之義，故於此爻足其意。蓋探本之論，與大象言“有物行有恆”相表裡。</p><p>象曰：威如之吉，反身之謂也</p><h3 id="本義-13" tabindex="-1">本義 <a class="header-anchor" href="#本義-13" aria-label="Permalink to “本義”">​</a></h3><p>謂非作威也，反身自治則人畏服之矣</p><h3 id="程傳-17" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-17" aria-label="Permalink to “程傳”">​</a></h3><p>治家之道，以正身為本。故云反身之謂。爻辭謂治家當有威嚴，而夫子又復戒雲當先嚴其身也。威嚴不先行於己，則人怨而不服。故云威如而吉者，能自反於身也。孟子所謂“身不行道，不行於妻子”也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱氏震曰：威非外求，反諸身而已。反身則正，正則誠，誠則不怒而威。後世不知所謂威嚴者，正其身也。或不正而尚威怒，則父子相夷，愈不服矣，安得吉？</p></li><li><p>郭氏雍曰：象明言“有物而行有恆”，而此又言“反身之謂”者，家人之道所以成始成終者，脩身而已。</p></li><li><p>趙氏汝梅曰：爻於初言閒，三言嗃嗃，上言威。聖人慮後世以為威嚴有餘而親睦不足，故特釋之以反身，謂威如者非嚴厲以為威，反求諸己而已。</p></li></ul><p>總論</p><p>吳氏曰 ：家人之道，男以剛嚴為正，女以柔順為正。初曰閒，三曰厲，上曰威，男子之道也；二、四象傳皆曰順，婦人之道也。五剛而中，非不嚴也，嚴而㤗也。</p>',154)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
